import{_ as s,c as n,S as e,o as t}from"./chunks/framework.BJg9xKzR.js";const h=JSON.parse('{"title":"Language Basics","description":"","frontmatter":{},"headers":[],"relativePath":"reference/language-basics.md","filePath":"reference/language-basics.md"}'),o={name:"reference/language-basics.md"};function i(l,a,p,r,c,u){return t(),n("div",null,a[0]||(a[0]=[e(`<h1 id="language-basics" tabindex="-1">Language Basics <a class="header-anchor" href="#language-basics" aria-label="Permalink to &quot;Language Basics&quot;">​</a></h1><h2 id="variables-and-types" tabindex="-1">Variables and Types <a class="header-anchor" href="#variables-and-types" aria-label="Permalink to &quot;Variables and Types&quot;">​</a></h2><p>A++ supports several basic data types:</p><div class="language-a++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">a++</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>// Numbers</span></span>
<span class="line"><span>num x = 42;          // Integer</span></span>
<span class="line"><span>float pi = 3.14;     // Floating-point number</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Text</span></span>
<span class="line"><span>text greeting = &quot;Hello, World!&quot;;  // String</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Booleans</span></span>
<span class="line"><span>bool isValid = yup;   // Boolean (yup/nope)</span></span></code></pre></div><h3 id="type-rules" tabindex="-1">Type Rules <a class="header-anchor" href="#type-rules" aria-label="Permalink to &quot;Type Rules&quot;">​</a></h3><ul><li>Strong typing: Variables must be declared with their type</li><li>Type inference is not supported</li><li>No implicit type conversion</li></ul><h2 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to &quot;Operators&quot;">​</a></h2><h3 id="arithmetic-operators" tabindex="-1">Arithmetic Operators <a class="header-anchor" href="#arithmetic-operators" aria-label="Permalink to &quot;Arithmetic Operators&quot;">​</a></h3><div class="language-a++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">a++</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>num a = 10;</span></span>
<span class="line"><span>num b = 3;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(a + b);    // Addition: 13</span></span>
<span class="line"><span>print(a - b);    // Subtraction: 7</span></span>
<span class="line"><span>print(a * b);    // Multiplication: 30</span></span>
<span class="line"><span>print(a / b);    // Division: 3</span></span>
<span class="line"><span>print(a % b);    // Modulus: 1</span></span></code></pre></div><h3 id="comparison-operators" tabindex="-1">Comparison Operators <a class="header-anchor" href="#comparison-operators" aria-label="Permalink to &quot;Comparison Operators&quot;">​</a></h3><div class="language-a++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">a++</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>print(5 == 5);   // Equal to: yup</span></span>
<span class="line"><span>print(5 != 10);  // Not equal to: yup</span></span>
<span class="line"><span>print(5 &gt; 3);    // Greater than: yup</span></span>
<span class="line"><span>print(5 &lt; 3);    // Less than: nope</span></span>
<span class="line"><span>print(5 &gt;= 5);   // Greater than or equal: yup</span></span>
<span class="line"><span>print(5 &lt;= 4);   // Less than or equal: nope</span></span></code></pre></div><h3 id="logical-operators" tabindex="-1">Logical Operators <a class="header-anchor" href="#logical-operators" aria-label="Permalink to &quot;Logical Operators&quot;">​</a></h3><div class="language-a++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">a++</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>bool a = yup;</span></span>
<span class="line"><span>bool b = nope;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>print(a &amp;&amp; b);   // Logical AND: nope</span></span>
<span class="line"><span>print(a || b);   // Logical OR: yup</span></span>
<span class="line"><span>print(!a);       // Logical NOT: nope</span></span></code></pre></div><h2 id="keywords" tabindex="-1">Keywords <a class="header-anchor" href="#keywords" aria-label="Permalink to &quot;Keywords&quot;">​</a></h2><p>A++ has several reserved keywords:</p><h3 id="type-keywords" tabindex="-1">Type Keywords <a class="header-anchor" href="#type-keywords" aria-label="Permalink to &quot;Type Keywords&quot;">​</a></h3><ul><li><code>num</code>: Integer numbers</li><li><code>float</code>: Floating-point numbers</li><li><code>text</code>: Text strings</li><li><code>bool</code>: Boolean values</li></ul><h3 id="control-flow-keywords" tabindex="-1">Control Flow Keywords <a class="header-anchor" href="#control-flow-keywords" aria-label="Permalink to &quot;Control Flow Keywords&quot;">​</a></h3><ul><li><code>if</code>: Conditional statements</li><li><code>else</code>: Alternative conditional branch</li><li><code>for</code>: Loop construct</li><li><code>while</code>: While loop</li><li><code>break</code>: Exit a loop</li><li><code>continue</code>: Skip to next iteration</li></ul><h3 id="boolean-values" tabindex="-1">Boolean Values <a class="header-anchor" href="#boolean-values" aria-label="Permalink to &quot;Boolean Values&quot;">​</a></h3><ul><li><code>yup</code>: True value</li><li><code>nope</code>: False value</li></ul><h3 id="other-keywords" tabindex="-1">Other Keywords <a class="header-anchor" href="#other-keywords" aria-label="Permalink to &quot;Other Keywords&quot;">​</a></h3><ul><li><code>print</code>: Output to console</li><li><code>yap</code>: Alternative output</li><li><code>echo</code>: Alternative output</li><li><code>return</code>: Return from function</li></ul><h2 id="built-in-functions" tabindex="-1">Built-in Functions <a class="header-anchor" href="#built-in-functions" aria-label="Permalink to &quot;Built-in Functions&quot;">​</a></h2><h3 id="output-functions" tabindex="-1">Output Functions <a class="header-anchor" href="#output-functions" aria-label="Permalink to &quot;Output Functions&quot;">​</a></h3><div class="language-a++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">a++</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>print(&quot;Hello&quot;);     // Standard output</span></span>
<span class="line"><span>yap(&quot;Hello&quot;);       // Alternative output</span></span>
<span class="line"><span>echo(&quot;Hello&quot;);      // Alternative output</span></span></code></pre></div><h3 id="type-conversion" tabindex="-1">Type Conversion <a class="header-anchor" href="#type-conversion" aria-label="Permalink to &quot;Type Conversion&quot;">​</a></h3><div class="language-a++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">a++</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>num x = 42;</span></span>
<span class="line"><span>text str = toString(x);    // Convert to string</span></span>
<span class="line"><span>num n = toNumber(&quot;42&quot;);    // Convert to number</span></span></code></pre></div><h3 id="math-functions" tabindex="-1">Math Functions <a class="header-anchor" href="#math-functions" aria-label="Permalink to &quot;Math Functions&quot;">​</a></h3><div class="language-a++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">a++</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>num max = max(5, 10);      // Returns 10</span></span>
<span class="line"><span>num min = min(5, 10);      // Returns 5</span></span>
<span class="line"><span>num abs = abs(-5);         // Returns 5</span></span></code></pre></div><h3 id="string-functions" tabindex="-1">String Functions <a class="header-anchor" href="#string-functions" aria-label="Permalink to &quot;String Functions&quot;">​</a></h3><div class="language-a++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">a++</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span>text str = &quot;Hello&quot;;</span></span>
<span class="line"><span>num len = length(str);     // Returns 5</span></span>
<span class="line"><span>text upper = toUpper(str); // Returns &quot;HELLO&quot;</span></span>
<span class="line"><span>text lower = toLower(str); // Returns &quot;hello&quot;</span></span></code></pre></div>`,32)]))}const b=s(o,[["render",i]]);export{h as __pageData,b as default};
